:root {
  --bg: #0B0C10;
  --text: #E5E7EB;
  --accent: #F2F0EB;
}
html[data-theme="light"] {
  --bg: #F7F5F0;
  --text: #1F2328;
  --accent: #0B0C10;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: Inter, system-ui, sans-serif;
}

.site-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 20px;
}

.logo {
  color: var(--accent);
  font-weight: 700;
  text-decoration: none;
}

.site-nav {
  display: flex;
  gap: 16px;
}

.site-nav a {
  color: var(--text);
  text-decoration: none;
}

main {
  padding: 0 20px 40px;
  max-width: 1100px;
  margin: 0 auto;
}

h1 {
  color: var(--accent);
  font-size: 36px;
  line-height: 1.15;
}

.lead {
  font-size: 18px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.cta {
  display: inline-block;
  padding: 12px 20px;
  border: 1px solid var(--accent);
  color: var(--accent);
  text-decoration: none;
}

.promo-strip {
  width: 640px;
  margin: 32px 0;
  padding: 12px 16px;
  background: #1A1C23;
}

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 16px;
}

.card {
  padding: 16px;
  background: #13151B;
}
